// Помощники для #357a06 «שמור שינויים» в редактировании объявления. ПРОД: ничего не пишем —
// PATCH business перехватывается и отвечается локально (на сервер не уходит), прочие не-GET — abort.
import { expect, Page, Request } from '@playwright/test';

export const SAFE_METHODS = ['GET', 'HEAD', 'OPTIONS'];
export const LOAD = { timeout: 20_000 };
export const SAVE = 'שמור שינויים';
export const NEXT = 'שלב הבא';
export const UPDATE = 'עדכן מודעה';
export const TITLE_PH = 'יופיע ככותרת של המודעה שלך';
export const PHONE_PH = 'טלפון ליצירת קשר*';

/** Объявление для тестов редактирования: своё объявление роли QA_EDIT_LISTING_ROLE (по умолчанию user). */
export const EDIT_ID = process.env.QA_EDIT_LISTING_ID || '';
export const EDIT_ROLE = process.env.QA_EDIT_LISTING_ROLE || 'user';
export const SKIP_REASON =
  'Нет своего объявления для редактирования: задай QA_EDIT_LISTING_ID=<id объявления> ' +
  '(и при необходимости QA_EDIT_LISTING_ROLE=<роль-владелец>, по умолчанию user). На проде у тестовых аккаунтов объявлений сейчас нет.';

/** Только блок записи: ни один не-GET не должен дойти до сервера. */
export async function blockWrites(page: Page) {
  const passed: string[] = [];
  await page.route('**/*', (route) =>
    SAFE_METHODS.includes(route.request().method()) ? route.fallback() : route.abort('blockedbyclient'),
  );
  page.on('requestfinished', (r: Request) => {
    if (!SAFE_METHODS.includes(r.method())) passed.push(`${r.method()} ${r.url()}`);
  });
  return passed;
}

export type Patch = { url: string; body: Record<string, unknown> };

/**
 * Режим редактирования: запоминает исходную строку объявления (GET business?id=eq.<id>),
 * перехватывает PATCH business?id=eq.<id> — тело в patches, ответ 200 локально (строка + изменения),
 * остальные не-GET — abort. passed — не-GET, которые всё-таки дошли до сервера (должно быть пусто).
 * ctl.patchStatus — код ответа на PATCH (по умолчанию 200; 500 — имитация ошибки сервера, #775eeb/#3bb8cb).
 */
export async function interceptEdit(page: Page, id: string) {
  const patches: Patch[] = [];
  const ctl = { patchStatus: 200 };
  const passed: string[] = [];
  const state: { row: Record<string, unknown> | null } = { row: null };
  const isBusinessRow = (url: string) => /\/rest\/v1\/business\?/.test(url) && url.includes(`id=eq.${id}`);

  page.on('response', async (res) => {
    const req = res.request();
    if (req.method() !== 'GET' || !isBusinessRow(res.url()) || state.row) return;
    try {
      const json = await res.json();
      const row = Array.isArray(json) ? json[0] : json;
      if (row && typeof row === 'object' && 'status' in row) state.row = row;
    } catch { /* не JSON */ }
  });

  await page.route('**/*', async (route) => {
    const req = route.request();
    const m = req.method();
    if (SAFE_METHODS.includes(m)) return route.fallback();
    if (m === 'PATCH' && isBusinessRow(req.url())) {
      let body: Record<string, unknown> = {};
      try { body = req.postDataJSON() ?? {}; } catch { /* пусто */ }
      patches.push({ url: req.url(), body });
      if (ctl.patchStatus >= 400) {
        return route.fulfill({
          status: ctl.patchStatus,
          contentType: 'application/json',
          body: JSON.stringify({ code: 'XX000', message: 'QA-AUTO simulated server error', details: null, hint: null }),
        });
      }
      return route.fulfill({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify([{ ...(state.row ?? { id }), ...body }]),
      });
    }
    return route.abort('blockedbyclient');
  });
  page.on('requestfinished', (r: Request) => {
    if (!SAFE_METHODS.includes(r.method()) && !(r.method() === 'PATCH' && isBusinessRow(r.url()))) {
      passed.push(`${r.method()} ${r.url()}`);
    }
  });
  return { patches, passed, state, ctl };
}

export async function openEdit(page: Page, id: string, state: { row: Record<string, unknown> | null }) {
  await page.goto(`/addbusiness?id=${id}`);
  await expect(page.getByRole('heading', { name: 'עריכת מודעה' }), 'режим «עריכת מודעה»').toBeVisible(LOAD);
  await expect(page.getByPlaceholder(TITLE_PH), 'заголовок объявления подгружен').not.toHaveValue('', LOAD);
  await expect.poll(() => state.row !== null, { message: 'строка объявления получена (GET business)', ...LOAD }).toBe(true);
}

/** Кнопки внизу шага: «שמור שינויים» + основная (שלב הבא / עדכן מודעה). */
export async function expectStepButtons(page: Page, primary: string, step: number) {
  await expect(page.getByRole('button', { name: SAVE, exact: true }), `шаг ${step}: «${SAVE}»`).toBeVisible(LOAD);
  await expect(page.getByRole('button', { name: primary }), `шаг ${step}: «${primary}»`).toBeVisible();
}

/** Нет повторных подтверждений (תנאי שימוש / הצהרת פרסום) и оплаты. */
export async function expectNoConfirmations(page: Page) {
  await expect(page.getByText('קראתי והבנתי את תקנון האתר'), 'нет повторного согласия с תקנון').toHaveCount(0);
  await expect(page.getByText(/אישור פרסום - אני מאשר/), 'нет «אישור פרסום»').toHaveCount(0);
  await expect(page.getByRole('dialog'), 'нет всплывающего окна').toHaveCount(0);
}
